{"file_path":"src/address.js","content":"/**
 * Cell address parsing and formatting. An address is one or two letters
 * naming a column (A..Z, then AA..ZZ) and one to three digits naming a row
 * of at least 1, case-insensitive.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Convert 1-2 letters (bijective base-26) to a 1-based column number. */
function lettersToColumn(letters) {
  let value = 0
  for (const ch of letters.toUpperCase()) {
    value = value * 26 + (ch.charCodeAt(0) - 64)
  }
  return value
}

/** Convert a 1-based column number back to its letters. */
function columnToLetters(column) {
  let n = column
  let s = ''
  while (n > 0) {
    n -= 1
    s = String.fromCharCode(65 + (n % 26)) + s
    n = Math.floor(n / 26)
  }
  return s
}

/**
 * Parse a token as a cell address. Returns { col, row } on success, or null
 * when the token is not one or two letters followed by one to three digits
 * naming a row of at least 1.
 */
function parseAddress(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = lettersToColumn(m[1])
  return { col, row }
}

/** The canonical, upper-cased display form of a column/row pair. */
function formatAddress({ col, row }) {
  return columnToLetters(col) + String(row)
}

/** A single sortable key: ascending column, then ascending row. */
function addressKey({ col, row }) {
  return col * 1000 + row
}

module.exports = { parseAddress, formatAddress, addressKey, columnToLetters, lettersToColumn }
"}

