{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

const TWO_CHAR_OPS = ['<>', '<=', '>=']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

/**
 * Tokenize a formula body. Returns an array of tokens, or null if a
 * character does not belong to the formula grammar's lexicon.
 */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'lparen' })
      i += 1
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen' })
      i += 1
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'comma' })
      i += 1
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'colon' })
      i += 1
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i += 1
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^\d+(\.\d+)?/.exec(text.slice(i))
      tokens.push({ type: 'number', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(text.slice(i))
      tokens.push({ type: 'word', value: m[0], upper: m[0].toUpperCase() })
      i += m[0].length
      continue
    }
    return null
  }
  return tokens
}
"}

