{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces an AST or null when
 * the token stream does not belong to the formula grammar.
 *
 * Precedence, loosest first: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^` (right-associative), then a leading `-`/`+` (binds tighter than `^`).
 * A range (`A1:B3`) is only accepted directly as a function call argument.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  atEnd() {
    return this.pos >= this.tokens.length
  }

  parseFormula() {
