{"file_path":"src/values.js","content":"/**
 * Literal cell content parsing and value formatting.
 */

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?\d+(\.\d+)?$/

/** Parse a non-formula cell body into a value: a number, an error, or text. */
export function parseLiteral(text) {
  if (text === '') return { type: 'number', value: 0 }
  if (ERROR_TOKENS.has(text)) return { type: 'error', value: text }
  if (NUMBER_RE.test(text)) return { type: 'number', value: Number(text) }
  return { type: 'text', value: text }
}

/** Round a finite number to ten significant digits. */
export function roundToTenSigFigs(x) {
  if (x === 0) return 0
  return Number(x.toPrecision(10))
}

/** Format a value the way `values` mode prints it. */
export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return String(roundToTenSigFigs(v.value))
    case 'error':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'text':
      return v.value
    default:
      throw new Error(`unknown value type: ${v.type}`)
  }
}
"}

