export function parseSheet(input) {
  const cells = new Map()
  const lines = splitLines(input)
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]*/, '')
    if (stripped === '' || stripped.startsWith('#')) continue
    const wsIndex = stripped.search(/[ \t]/)
    let addressText
    let content
    if (wsIndex === -1) {
      addressText = stripped
      content = ''
    } else {
      addressText = stripped.slice(0, wsIndex)
      const rest = stripped.slice(wsIndex)
      const run = /^[ \t]+/.exec(rest)
      content = rest.slice(run[0].length)
