{"file_path":"src/evaluate.js","content":"/**
 * Formula evaluation: turns declared cell contents into values, resolving
 * cell references lazily and detecting reference cycles.
 */

import { parseAddress, addressKey } from './address.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGGREGATE_FNS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

/** Thrown internally to unwind the call stack back to a cycle's own frame. */
class CycleSignal {
  constructor(key) {
    this.key = key
  }
}

function toNumber(v) {
  if (v.type === 'number') return { num: v.value }
  if (v.type === 'bool') return { num: v.value ? 1 : 0 }
  if (v.type === 'error') return { err: v.value }
  return { err: '#VALUE!' }
}

function toBoolean(v) {
  if (v.type === 'bool') return { bool: v.value }
  if (v.type === 'number') return { bool: v.value !== 0 }
  if (v.type === 'error') return { err: v.value }
  return { err: '#VALUE!' }
}

function typeRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // bool
}

function compareValues(l, r) {
  const rl = typeRank(l)
  const rr = typeRank(r)
  if (rl !== rr) return rl - rr
  if (rl === 0) return l.value - r.value
  if (rl === 1) return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  return (l.value ? 1 : 0) - (r.value ? 1 : 0)
}

function compare(op, l, r) {
  const diff = compareValues(l, r)
  switch (op) {
    case '=':
      return diff === 0
    case '<>':
      return diff !== 0
    case '<':
      return diff < 0
    case '<=':
      return diff <= 0
    case '>':
      return diff > 0
    case '>=':
      return diff >= 0
    default:
      throw new Error(`unknown comparison: ${op}`)
  }
}

function arithmetic(op, a, b) {
  switch (op) {
    case '+':
      return a + b
    case '-':
      return a - b
    case '*':
      return a * b
    case '/':
      return a / b
    case '^':
      return Math.pow(a, b)
    default:
      throw new Error(`unknown operator: ${op}`)
  }
}

function firstError(vals) {
  for (const v of vals) if (v.type === 'error') return v
  return null
}

function evalCellRef(word, ctx) {
  const addr = parseAddress(word)
  if (!addr) return { type: 'error', value: '#REF!' }
  return ctx.evalCell(addressKey(addr))
}

function rangeCells(from, to) {
  const a = parseAddress(from)
  const b = parseAddress(to)
  if (!a || !b) return null
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      cells.push({ col: c, row: r })
    }
  }
  return cells
}

/** Evaluate one function-call argument (a range or an expression) to a
 *  flat list of values, in ascending column then row order for ranges. */
function flattenArg(node, ctx) {
  if (node.type === 'range') {
    const cells = rangeCells(node.from, node.to)
    if (cells === null) return [{ type: 'error', value: '#REF!' }]
    return cells.map((c) => ctx.evalCell(addressKey(c)))
  }
  return [evalNode(node, ctx)]
}

function flattenArgs(nodes, ctx) {
  const vals = []
  for (const node of nodes) vals.push(...flattenArg(node, ctx))
  return vals
}

function evalBinOp(node, ctx) {
  const left = evalNode(node.left, ctx)
  const right = evalNode(node.right, ctx)
  if (COMPARISON_OPS.has(node.op)) {
    if (left.type === 'error') return left
    if (right.type === 'error') return right
    return { type: 'bool', value: compare(node.op, left, right) }
  }
  if (left.type === 'error') return left
  if (right.type === 'error') return right
  const ln = toNumber(left)
  if (ln.err) return { type: 'error', value: ln.err }
  const rn = toNumber(right)
  if (rn.err) return { type: 'error', value: rn.err }
  const result = arithmetic(node.op, ln.num, rn.num)
  if (!Number.isFinite(result)) return { type: 'error', value: '#DIV/0!' }
  return { type: 'number', value: result }
}

function evalUnary(node, ctx) {
  const v = evalNode(node.operand, ctx)
  if (v.type === 'error') return v
  const n = toNumber(v)
  if (n.err) return { type: 'error', value: n.err }
  const result = node.op === '-' ? -n.num : n.num
  if (!Number.isFinite(result)) return { type: 'error', value: '#DIV/0!' }
  return { type: 'number', value: result }
}

function evalCall(node, ctx) {
  const name = node.name
  if (name === 'IF') {
    if (node.args.length !== 3) return { type: 'error', value: '#ERR!' }
    const condVals = flattenArg(node.args[0], ctx)
    const condErr = firstError(condVals)
    if (condErr) return condErr
    const cond = toBoolean(condVals[0])
    if (cond.err) return { type: 'error', value: cond.err }
    const branch = cond.bool ? node.args[1] : node.args[2]
    const branchVals = flattenArg(branch, ctx)
    const branchErr = firstError(branchVals)
    if (branchErr) return branchErr
    return branchVals[0]
  }
  if (name === 'ABS') {
    if (node.args.length !== 1) return { type: 'error', value: '#ERR!' }
    const vals = flattenArg(node.args[0], ctx)
    const err = firstError(vals)
    if (err) return err
    const n = toNumber(vals[0])
    if (n.err) return { type: 'error', value: n.err }
    const result = Math.abs(n.num)
    if (!Number.isFinite(result)) return { type: 'error', value: '#DIV/0!' }
    return { type: 'number', value: result }
  }
  if (AGGREGATE_FNS.has(name)) {
    if (node.args.length < 1) return { type: 'error', value: '#ERR!' }
    const vals = flattenArgs(node.args, ctx)
    const err = firstError(vals)
    if (err) return err
    if (name === 'COUNT') {
      return { type: 'number', value: vals.filter((v) => v.type === 'number').length }
    }
    const nums = []
    for (const v of vals) {
      const n = toNumber(v)
      if (n.err) return { type: 'error', value: n.err }
      nums.push(n.num)
    }
    if (name === 'SUM') {
      const total = nums.reduce((a, b) => a + b, 0)
      if (!Number.isFinite(total)) return { type: 'error', value: '#DIV/0!' }
      return { type: 'number', value: total }
    }
    if (name === 'AVG') {
      const avg = nums.reduce((a, b) => a + b, 0) / nums.length
      if (!Number.isFinite(avg)) return { type: 'error', value: '#DIV/0!' }
      return { type: 'number', value: avg }
    }
    if (name === 'MIN') return { type: 'number', value: Math.min(...nums) }
    if (name === 'MAX') return { type: 'number', value: Math.max(...nums) }
  }
  return { type: 'error', value: '#NAME?' }
}

function evalNode(node, ctx) {
  switch (node.type) {
    case 'num':
      return { type: 'number', value: node.value }
    case 'bool':
      return { type: 'bool', value: node.value }
    case 'cell':
      return evalCellRef(node.word, ctx)
    case 'binop':
      return evalBinOp(node, ctx)
    case 'unary':
      return evalUnary(node, ctx)
    case 'call':
      return evalCall(node, ctx)
    default:
      throw new Error(`unexpected node type: ${node.type}`)
  }
}

function computeContent(content, ctx) {
  if (content.startsWith('=')) {
    const ast = parseFormula(content.slice(1))
    if (ast === null) return { type: 'error', value: '#ERR!' }
    return evalNode(ast, ctx)
  }
  return parseLiteral(content)
}

/**
 * Build an evaluator over a sheet. `cellsByKey` maps an address key to its
 * declaration `{ content }`. Returns a function that resolves an address
 * key to its value, memoizing results and turning self-reaching references
 * into `#CYCLE!`.
 */
export function createEvaluator(cellsByKey) {
  const memo = new Map()
  const visiting = new Set()

  function evalCell(key) {
    if (memo.has(key)) return memo.get(key)
    const decl = cellsByKey.get(key)
    if (!decl) {
      const v = { type: 'number', value: 0 }
      memo.set(key, v)
      return v
    }
    if (visiting.has(key)) throw new CycleSignal(key)
    visiting.add(key)
    try {
      const result = computeContent(decl.content, { evalCell })
      visiting.delete(key)
      memo.set(key, result)
      return result
    } catch (e) {
      if (!(e instanceof CycleSignal)) throw e
      visiting.delete(key)
      const result = { type: 'error', value: '#CYCLE!' }
      memo.set(key, result)
      if (e.key !== key) throw e
      return result
    }
  }

  return evalCell
}
"}

