 * Syntactic dependency collection: which cells a formula's AST names
 * directly, independent of how it would evaluate (so an untaken `IF`
 * branch still counts, and a range names every cell it covers).
 */

import { parseAddress, addressKey } from './address.js'

function addCellRef(word, keys) {
  const addr = parseAddress(word)
  if (addr) keys.add(addressKey(addr))
}

function addRange(from, to, keys) {
  const a = parseAddress(from)
  const b = parseAddress(to)
  if (!a || !b) return
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      keys.add(addressKey({ col: c, row: r }))
    }
  }
}

function walk(node, keys) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'cell':
      addCellRef(node.word, keys)
      return
    case 'range':
      addRange(node.from, node.to, keys)
      return
    case 'binop':
      walk(node.left, keys)
      walk(node.right, keys)
      return
    case 'unary':
      walk(node.operand, keys)
      return
    case 'call':
      for (const arg of node.args) walk(arg, keys)
      return
    default:
      throw new Error(`unexpected node type: ${node.type}`)
  }
}

