{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { columnToLetters, addressKey } from './address.js'
import { parseFormula } from './parser.js'
import { collectDeps } from './deps.js'
import { createEvaluator } from './evaluate.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const cellsByKey = new Map(cells.map((c) => [c.key, c]))

  const lines = []
  if (mode === 'values') {
    const evalCell = createEvaluator(cellsByKey)
    for (const cell of cells) {
      const value = evalCell(cell.key)
      lines.push(`${cell.address}=${formatValue(value)}`)
    }
  } else {
    for (const cell of cells) {
      let depsText = ''
      if (cell.content.startsWith('=')) {
        const ast = parseFormula(cell.content.slice(1))
        if (ast !== null) {
          const keys = [...collectDeps(ast)].sort((a, b) => a - b)
          depsText = keys.map((k) => ` ${columnToLetters(Math.floor(k / 1000))}${k % 1000}`).join('')
        }
      }
      lines.push(`${cell.address}:${depsText}`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

